Seluruh — /* Base content styles */
        .sanitized-content {
          line-height: 1.6;
        }

        /* Bold text styles */
        .sanitized-content b,
        .sanitized-content strong {
          font-weight: 700;
        }

        /* Heading styles */
        .sanitized-content h1 {
          font-size: 2.5rem;
          font-weight: 700;
          margin: 2rem 0 1rem;
        }

        .sanitized-content h2 {
          font-size: 2rem;
          font-weight: 600;
          margin: 1.75rem 0 0.875rem;
        }

        .sanitized-content h3 {
          font-size: 1.75rem;
          font-weight: 600;
          margin: 1.5rem 0 0.75rem;
        }

        .sanitized-content h4 {
          font-size: 1.5rem;
          font-weight: 600;
          margin: 1.25rem 0 0.625rem;
        }

        .sanitized-content h5 {
          font-size: 1.25rem;
          font-weight: 600;
          margin: 1rem 0 0.5rem;
        }

        .sanitized-content h6 {
          font-size: 1.1rem;
          font-weight: 600;
          margin: 0.875rem 0 0.4375rem;
        }

        /* Paragraph styles */
        .sanitized-content p {
          margin-bottom: 1rem;
        }

        /* List styles */
        .sanitized-content ul {
          list-style-type: disc;
          margin: 1rem 0;
          padding-left: 1.5rem;
        }

        .sanitized-content li {
          margin-bottom: 0.5rem;
        }

        .sanitized-content ol {
          list-style-type: decimal;
          margin: 1rem 0;
          padding-left: 1.5rem;
        }

        .sanitized-content ol[type="a"] {
          list-style-type: lower-alpha;
        }

        .sanitized-content .d-block.d-sm-inline ol {
          counter-reset: listCounter 4;
        }

        /* Table styles */
        .sanitized-content table {
          width: 100%;
          border-collapse: collapse;
          margin: 1rem 0;
        }

        .sanitized-content td {
          padding: 0.5rem;
          border: 1px solid #e2e8f0;
        }

        /* Link styles */
        .sanitized-content a {
          color: #2563eb;
          text-decoration: underline;
        }

        .sanitized-content a:hover {
          color: #1d4ed8;
        }

        /* Image styles */
        .sanitized-content img {
          max-width: 100%;
          height: auto;
          margin: 1rem 0;
        }

        /* Responsive adjustments */
        @media (max-width: 768px) {
          .sanitized-content h1 { font-size: 2rem; }
          .sanitized-content h2 { font-size: 1.75rem; }
          .sanitized-content h3 { font-size: 1.5rem; }
          .sanitized-content h4 { font-size: 1.25rem; }
          .sanitized-content h5 { font-size: 1.1rem; }
          .sanitized-content h6 { font-size: 1rem; }
        }
